INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Organic or Chemical?', '选择性必修一 U5 · dialogue', 3, 'Anna: These apples are cheaper, but I''m buying the organic ones.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·短文 A Man of the Soil', '选择性必修一 U5 · passage', 2, 'Yuan Longping spent his whole life working the land.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U5 听力·对话 Helping on the Farm', '选择性必修一 U5 · dialogue', 3, 'Grandpa: Could you help me in the fields this weekend, Kate?
