INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write an Argumentative Essay on Organic Farming(就有机农业写一篇议论文)', 'Why I Support Organic Farming', '假设你叫李华,你们班正就''化学农业 vs 有机农业''展开讨论。请用英语写一篇约100词的议论文,内容包括:① 明确表态你支持哪一种农业(化学/有机);② 给出两到三条理由,每条理由配一个细节;③ 写一句总结。注意:观点鲜明、条理清楚、句句围绕主题。', 'Suppose you are Li Hua. Your class is discussing ''chemical farming versus organic farming''. Write an argumentative essay (about 100 words) including: 1) a clear statement of which kind of farming you support; 2) two or three reasons, each with a supporting detail; 3) a short conclusion. Make your opinion clear and keep every sentence on topic.', '["亮明观点(In my opinion, organic farming is preferable to chemical farming.)","理由+细节1(First, organic food is safer, because no chemicals stay in the soil or the food.)","理由+细节2(Second, organic methods protect the land, for example by changing crops every year.)","总结(All in all, organic farming is better for our health and our environment.)"]'::jsonb, 70, 100, 'Recently our class has been discussing chemical farming and organic farming. In my opinion, organic farming is preferable to chemical farming. First, organic food is safer for our health. Growing crops without pesticides means that no harmful chemicals stay in the soil or in the food we eat. Second, organic methods protect the land. For instance, organic farmers change the kind of crop in each field every year, which keeps the soil rich in minerals. Of course, organic farming cannot yet feed the whole world by itself. Even so, I believe that growing food in this natural way is better for both our health and our environment.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["In my opinion, organic farming is preferable to chemical farming.","Growing crops without pesticides means that no harmful chemicals stay in the soil or in the food we eat.","Organic farmers change the kind of crop in each field every year, which keeps the soil rich in minerals.","Growing food in this natural way is better for both our health and our environment."]'::jsonb, '[{"wrong":"Grow crops without chemicals are safer.","correct":"Growing crops without chemicals is safer.","note":"动名词作主语,谓语用单数 is;不能用动词原形 Grow。"},{"wrong":"It is no use to use too many pesticides.","correct":"It is no use using too many pesticides.","note":"It is no use doing 固定句式,用动名词。"},{"wrong":"Organic farming protect the land.","correct":"Organic farming protects the land.","note":"主语第三人称单数,谓语动词加 s。"}]'::jsonb, '【农业议论文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'elective1', 'U5', '{"title":"动名词(-ing form)作主语 速查","intro":"把一个动作''名词化''放到句首当主语,就用动名词(doing)。动名词作主语时看作单数,谓语用 is/was/feeds 等单数形式。常与 it 形式主语、no use/no point 等固定句式搭配。","table":{"headers":["用法","例句 / 说明"],"rows":[["动名词直接作主语","Growing rice feeds millions.(谓语用单数 feeds)"],["it 作形式主语","It is no use crying over spilt milk.(真正主语是 crying)"],["no point / waste of time","There is no point (in) waiting. / It''s a waste of time complaining."],["复合结构作主语","Tom''s / His coming made us happy.(所有格 + doing)"],["动名词 vs 不定式","动名词主语=泛指/一般;不定式主语=具体/将来(常用 it 形式)"]]},"specialRules":[{"rule":"动名词作主语 → 谓语永远用单数","mark":"Reading widens our minds.（widens 单数）"},{"rule":"It is no use / no good doing … 只能跟动名词,不能跟不定式","mark":"It is no use crying √ / to cry ×"},{"rule":"There is no point (in) doing …;a waste of time doing …","mark":"no point waiting √"},{"rule":"动名词前可加名词所有格/形容词性物主代词作逻辑主语","mark":"his coming / Tom''s leaving"}],"why":["动名词兼具''动词''(有动作含义、可带宾语)和''名词''(可作主语)的双重身份,所以能稳稳地占住句首主语的位置;而 does/done 没有名词性,不能作主语。"],"gaokaoPoints":["句首主语位的填空:动名词 vs 动词原形/第三人称单数/过去分词——只有动名词能作主语,谓语用单数。","固定句式 It is no use/no good doing、There is no point (in) doing、a waste of time doing——高频考动名词。","动名词主语(泛指、一般)与不定式主语(具体、将来,常用 it 形式主语)的选用对照。"],"examVsReal":[{"exam":"Smoking is bad for your health.（考试/正式)","real":"Smoking? Bad for you.","note":"考试用完整动名词主语句;口语里常省略谓语、用碎句"},{"exam":"It is no use crying over spilt milk.（书面谚语)","real":"No point crying about it.","note":"口语里 It is 常省略,直接 No point doing"}]}'::jsonb);
